// Turn active client_config rows into a lookup keyed by client_code.
// Unlike a strict all-or-nothing parse, a bad or missing JSON field degrades
// gracefully per field (logged in config_problems) rather than skipping the
// whole client -- one typo in source_b_field_map_json should not take down
// Source A parsing for the same client, or vice versa.
const run = $('Set Run Context').first().json;
const rows = $input.all().map(i => i.json).map(j => j.fields || j).filter(f => f && f.client_code);

const clients = [];
const problems = [];
for (const f of rows) {
  const code = String(f.client_code).trim().toUpperCase();
  const parseJson = (raw, label) => {
    if (!raw) return null;
    try { return JSON.parse(raw); }
    catch (e) { problems.push(code + ': ' + label + ' is not valid JSON'); return null; }
  };

  const columnMap = parseJson(f.column_map_json, 'column_map_json');
  const statusMap = parseJson(f.status_map_json, 'status_map_json') || {};
  const validCurrenciesRaw = parseJson(f.valid_currencies_json, 'valid_currencies_json');
  const validCurrencies = Array.isArray(validCurrenciesRaw) ? validCurrenciesRaw.map(c => String(c).toUpperCase()) : [];
  if (f.valid_currencies_json && !Array.isArray(validCurrenciesRaw)) problems.push(code + ': valid_currencies_json must be a JSON array, e.g. ["EUR","USD"]');

  const sourceBMap = parseJson(f.source_b_field_map_json, 'source_b_field_map_json');
  const sourceCMap = parseJson(f.source_c_field_map_json, 'source_c_field_map_json');
  const orderRefNormalizeB = parseJson(f.order_ref_normalize_b_json, 'order_ref_normalize_b_json');
  const fieldPrecedence = parseJson(f.field_precedence_json, 'field_precedence_json') || { default: 'source_a', fields: {} };

  clients.push({
    client_code: code,
    client_name: f.client_name || code,
    columnMap, statusMap, validCurrencies,
    dateFormats: String(f.date_formats || '').split(',').map(s => s.trim()).filter(Boolean),
    sourceBMap, sourceCMap, orderRefNormalizeB, fieldPrecedence,
  });
}
return [{ json: { run_id: run.run_id, clients, config_problems: problems } }];

// Parses this file's binary JSON payload into a flat array of order objects.
// ADJUST ROOT_PATH once you've inspected your real meridian_ecommerce_day1.json:
//   '' if the file's top level is already an array of orders
//   'orders' or 'data' (etc.) if orders sit under a wrapper key
const ROOT_PATH = 'orders';

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
let parsed;
try { parsed = JSON.parse(buf.toString('utf-8')); }
catch (e) { throw new Error('Source B file is not valid JSON: ' + e.message); }

let orders = parsed;
if (ROOT_PATH) { orders = ROOT_PATH.split('.').reduce((acc, k) => (acc || {})[k], parsed); }
if (!Array.isArray(orders)) orders = [orders];

return orders.map(o => ({ json: o }));

// Reconcile Source B (e-commerce JSON) rows against existing canonical_lines.
//
// PRECEDENCE RULE (stated for the write-up):
// If only one source has a non-null value for a field, that value is used -- no conflict.
// If both Source A and Source B report a non-null value and they differ, the winner is chosen
// per client_config.field_precedence_json (per-field override, else .default). The rule is NOT
// applied silently: conflict_flag is set true, the losing AND winning values are both written to
// conflict_values_json, and an Exceptions row is logged with issue_type 'cross_source_conflict'.
// Default policy used here: Source A (warehouse) is authoritative for quantity/price/cost/currency
// /vat (it reflects what was physically picked and invoiced); Source B (e-commerce) is authoritative
// for customer_name/customer_email/order_status (it's the system the customer directly interacts
// with and is updated closer to real time). Encode this per client in field_precedence_json.
//
// MATCHING RULE: Source B's order reference is normalized via order_ref_normalize_b_json (regex
// extract + canonical prefix/padding) so it lines up with Source A's canonical_line_id format.
// Within an order, a Source B line is matched to an existing canonical line by SKU when both sides
// have one; otherwise by positional index. An order/line present in B with no Source A match still
// gets a canonical row (sources_seen='B') and a high-severity 'order_only_in_source_b' exception --
// Part 2 requirement: an order in Source B but never in Source A must not be silently dropped.
//
// Existing fields on a matched canonical row that Source B does not report (product_string_raw,
// stated_line_total, sales_rep, etc.) are carried forward untouched -- only the fields Source B
// actually reconciles are ever overwritten.

function num(v) { if (v === undefined || v === null || v === '') return null; const n = parseFloat(String(v).replace(/,/g, '')); return Number.isFinite(n) ? n : null; }
function djb2(str) { let h = 5381; for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0; return h.toString(16); }
const SKU_RE = /\b([A-Za-z]{2,4})-{1,2}(\d{3,5})-([A-Za-z0-9]{1,3})\b/;
function extractSku(text) { const m = String(text || '').match(SKU_RE); if (!m) return null; return `${m[1].toUpperCase()}-${m[2]}-${m[3].toUpperCase()}`; }
function getPath(obj, path) { if (!path) return undefined; return path.split('.').reduce((acc, key) => (acc == null ? undefined : acc[key]), obj); }
function normalizeOrderRef(raw, cfg) {
  const s = String(raw || '').trim();
  if (!cfg || !cfg.extract_regex) return s.toUpperCase();
  const m = s.match(new RegExp(cfg.extract_regex));
  if (!m) return s.toUpperCase();
  const digits = m[1].padStart(cfg.pad_length || 0, '0');
  return `${cfg.canonical_prefix || ''}${digits}`;
}

const ctx = $('Build Client Routes').first().json;
const run = $('Set Run Context').first().json;
const fileRun = $('Loop Over Pending Files').first().json;
const client = ctx.clients.find(c => c.client_code === fileRun.client_code);

const exceptions = [];
const summary = { rows_read: 0, rows_written: 0, rows_rejected: 0, rows_duplicate_ignored: 0, rows_conflict: 0, rows_review: 0 };

function pushException(orderRef, lineNo, issueType, description, valueSeen, valueAlternative, actionTaken, severity) {
  exceptions.push({ json: { _kind: 'exception',
    exception_id: `${fileRun.client_code}|${orderRef}|${lineNo}|${issueType}`,
    run_id: run.run_id, client_code: fileRun.client_code, source_type: 'source_b', source_file_id: fileRun.file_id,
    order_ref: orderRef, line_no: String(lineNo), issue_type: issueType, description,
    value_seen: valueSeen == null ? '' : String(valueSeen),
    value_alternative: valueAlternative == null ? '' : String(valueAlternative),
    action_taken: actionTaken, severity, created_at: new Date().toISOString(), resolved: false,
  }});
}

if (!client || !client.sourceBMap) {
  return [{ json: { _kind: 'file_summary', ...summary, run_id: run.run_id, file_run_id: fileRun.id,
    client_code: fileRun.client_code, note: 'client_code not found, or source_b_field_map_json missing/invalid -- file skipped' } }];
}
const map = client.sourceBMap;
const precedence = client.fieldPrecedence || { default: 'source_a', fields: {} };
const refCfg = client.orderRefNormalizeB || null;

const rawOrders = $('Parse Source B JSON').all().map(i => i.json);

const existingByRef = new Map();
for (const item of $('Search Existing Canonical For Client').all()) {
  const f = item.json.fields || item.json;
  if (!f.order_ref) continue;
  const ref = String(f.order_ref).trim().toUpperCase();
  if (!existingByRef.has(ref)) existingByRef.set(ref, []);
  existingByRef.get(ref).push({ airtableId: item.json.id, fields: f });
}

const CANON_FIELDS = ['order_date_iso', 'customer_name_clean', 'customer_email_clean', 'sales_rep', 'split_rep', 'split_pct', 'sku', 'quantity', 'unit_price', 'cost_price', 'currency', 'vat_rate', 'order_status'];
const canonicalOut = [];

for (const order of rawOrders) {
  const orderRefRaw = getPath(order, map.order_ref);
if (!orderRefRaw) {
   summary.rows_rejected++;
   const rejectId = `row${rawOrders.indexOf(order)}-${djb2(JSON.stringify(order)).slice(0,6)}`;
   pushException(rejectId, 1, 'missing_order_ref', 'Source B order has no value at the configured   order_ref path', map.order_ref, JSON.stringify(Object.keys(order)), 'Row skipped', 'high');
  continue;
}
  const orderRef = normalizeOrderRef(orderRefRaw, refCfg);

  const items = (map.line_items_path ? getPath(order, map.line_items_path) : null) || [order];
  const existingLines = existingByRef.get(orderRef) || [];

  items.forEach((item, idx) => {
    summary.rows_read++;
    const lf = map.line_item_fields || {};
    const skuRaw = getPath(item, lf.sku);
    const productString = getPath(item, lf.product_string) || '';
    const sku = skuRaw || extractSku(productString);
    const quantity = num(getPath(item, lf.quantity));
    const unitPrice = num(getPath(item, lf.unit_price));
    const currency = String(getPath(order, map.currency) || '').trim().toUpperCase() || null;
    const statusRaw = String(getPath(order, map.status) || '').trim().toLowerCase();
    const orderStatus = client.statusMap[statusRaw] || null;
    const dateRaw = getPath(order, map.order_date);
    const dateIso = dateRaw ? String(dateRaw).slice(0, 10) : null;

    let match = existingLines.find(e => e.fields.sku && sku && e.fields.sku === sku);
    if (!match) match = existingLines[idx];
    const lineNo = match ? match.fields.line_no : (idx + 1);

    if (!match) {
      summary.rows_written++;
      canonicalOut.push({ json: { _kind: 'canonical',
        canonical_line_id: `${fileRun.client_code}|${orderRef}|${lineNo}`, run_id: run.run_id, client_code: fileRun.client_code,
        source_type: 'source_b', order_ref: orderRef, line_no: lineNo,
        order_date_iso: dateIso, customer_name_clean: getPath(order, map.customer_name) || null,
        customer_email_clean: getPath(order, map.customer_email) || null,
        sku, quantity, unit_price: unitPrice, currency, order_status: orderStatus,
        intake_status: 'review', conflict_flag: false, conflict_fields: '', conflict_values_json: '',
        sources_seen: 'B', payload_hash: djb2(JSON.stringify({ quantity, unitPrice, sku })),
        last_seen_file_id: fileRun.file_id, last_seen_run_id: run.run_id, updated_at: new Date().toISOString(),
      }});
      pushException(orderRef, lineNo, 'order_only_in_source_b', 'Order/line found in Source B with no matching Source A record', fileRun.file_name, 'none in Source A', 'Canonical record created from Source B alone; needs Source A confirmation', 'high');
      return;
    }

const bValues = { order_date_iso: dateIso, customer_name_clean: getPath(order, map.customer_name) || null,
          customer_email_clean: getPath(order, map.customer_email) || null, sales_rep: getPath(order,          map.sales_rep) || null,sku, quantity, unit_price: unitPrice, currency, order_status: orderStatus };

    const resolved = {}; const conflictingFields = []; const bothValues = [];
    for (const f of CANON_FIELDS) {
      const aVal = match.fields[f] ?? null;
      const bVal = bValues.hasOwnProperty(f) ? bValues[f] : undefined;
      if (bVal === undefined || bVal === null || bVal === '') { resolved[f] = aVal; continue; }
      if (aVal === null || aVal === undefined || aVal === '') { resolved[f] = bVal; continue; }
      if (String(aVal) === String(bVal)) { resolved[f] = aVal; continue; }
      const winner = (precedence.fields[f] || precedence.default) === 'source_b' ? bVal : aVal;
      resolved[f] = winner;
      conflictingFields.push(f);
      bothValues.push({ field: f, source_a: aVal, source_b: bVal, used: winner });
    }

    const isConflict = conflictingFields.length > 0;
    if (isConflict) {
      summary.rows_conflict++;
      pushException(orderRef, lineNo, 'cross_source_conflict',
        `Fields differ between Source A and Source B: ${conflictingFields.join(', ')}`,
        JSON.stringify(Object.fromEntries(bothValues.map(v => [v.field, v.source_a]))),
        JSON.stringify(Object.fromEntries(bothValues.map(v => [v.field, v.source_b]))),
        `Resolved per field_precedence_json (default: ${precedence.default}); both values preserved in conflict_values_json`, 'high');
    }
    summary.rows_written++;

    const existingSources = new Set(String(match.fields.sources_seen || 'A').split('+').filter(Boolean));
    existingSources.add('B');

    const merged = { ...match.fields };
    for (const f of CANON_FIELDS) merged[f] = resolved[f];

    canonicalOut.push({ json: { _kind: 'canonical',
      canonical_line_id: `${fileRun.client_code}|${orderRef}|${lineNo}`, run_id: run.run_id, client_code: fileRun.client_code,
      source_type: [...existingSources].sort().join('+'), order_ref: orderRef, line_no: lineNo,
      order_date_raw: merged.order_date_raw || '', order_date_iso: merged.order_date_iso,
      customer_name_raw: merged.customer_name_raw || '', customer_name_clean: merged.customer_name_clean,
      customer_email_raw: merged.customer_email_raw || '', customer_email_clean: merged.customer_email_clean,
      sales_rep: merged.sales_rep, split_rep: merged.split_rep, split_pct: merged.split_pct,
      product_string_raw: merged.product_string_raw || '', sku: merged.sku, quantity: merged.quantity,
      unit_price: merged.unit_price, cost_price: merged.cost_price,
      stated_line_total: merged.stated_line_total, computed_line_total: merged.computed_line_total,
      line_total_mismatch: merged.line_total_mismatch, currency: merged.currency, vat_rate: merged.vat_rate,
      order_status: merged.order_status,
      intake_status: isConflict ? 'conflict' : (merged.intake_status || 'review'),
      conflict_flag: isConflict, conflict_fields: conflictingFields.join(','),
      conflict_values_json: isConflict ? JSON.stringify(bothValues) : (merged.conflict_values_json || ''),
      sources_seen: [...existingSources].sort().join('+'),
      payload_hash: djb2(JSON.stringify(resolved)),
      last_seen_file_id: fileRun.file_id, last_seen_run_id: run.run_id, updated_at: new Date().toISOString(),
    }});
  });
}

const out = [...canonicalOut, ...exceptions];
out.push({ json: { _kind: 'file_summary', ...summary, run_id: run.run_id, file_run_id: fileRun.id, client_code: fileRun.client_code, note: '' } });
return out;

// Aggregate this run's Source B reconciliation results into one run_summary row.
const run = $('Set Run Context').first().json;
const rows = $input.all().map(i => i.json.fields || i.json).filter(f => f.run_id === run.run_id);
const sum = (k) => rows.reduce((a, r) => a + (Number(r[k]) || 0), 0);
const filesTouched = rows.length;
const clients = [...new Set(rows.map(r => r.client_code))];
return [{ json: {
  run_id: run.run_id, stage: 'reconcile_source_b', execution_mode: run.execution_mode, started_at: run.started_at,
  finished_at: new Date().toISOString(), status: filesTouched ? 'reconcile_complete' : 'reconcile_complete_no_files',
  active_clients: clients.length, files_listed: filesTouched, files_new: 0, files_already_received: 0, files_unrecognised: 0,
  rows_read: sum('rows_read'), rows_written: sum('rows_written'), rows_rejected: sum('rows_rejected'),
  rows_duplicate_ignored: sum('rows_duplicate_ignored'), rows_conflict: sum('rows_conflict'),
  notes: filesTouched ? `Reconciled ${filesTouched} Source B file(s) for ${clients.join(', ')}` : 'No pending Source B file_runs found (status=received)',
} }];
